#!/usr/bin/env python3
from pathlib import Path
import json
import re
import subprocess

ROOT = Path(__file__).resolve().parents[1]
PROBLEM = ROOT / "problems/E-klein-cubic"
NOTEBOOK = PROBLEM / "NOTEBOOK.md"
MANIFEST = PROBLEM / "notebook_build/manifest.json"
DEGREE = PROBLEM / "goal_runs_20260810/RT_SPLIT_AND_DICHOTOMY/DEGREE_ACCOUNTING.md"
HEAD = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=ROOT, text=True).strip()
FINAL_HEADING = "## 2026-08-10 RT split, restricted dichotomy, and support-escape audit"

text = NOTEBOOK.read_text(encoding="utf-8")

# Remove the stale interim publication entry.  Its degree window and local
# specialization language were superseded by the audited entry immediately
# following it.
pattern = re.compile(
    r"\n## 2026-08-10 RT split completion and correction\n.*?"
    r"(?=\n## 2026-08-10 RT split, restricted dichotomy, and support-escape audit\n)",
    re.S,
)
text, count = pattern.subn("\n", text, count=1)
if count != 1:
    raise SystemExit("stale interim RT entry not found exactly once")

needle = FINAL_HEADING + "\n\nPacket:"
replacement = (
    FINAL_HEADING
    + "\n\nThis entry supersedes the earlier same-day packet-opened entry and all "
      "interim RT-split publication notes.\n\nPacket:"
)
if text.count(needle) != 1:
    raise SystemExit("final RT heading/packet marker not found exactly once")
text = text.replace(needle, replacement, 1)

# Notebook protocol: pin the pre-commit parent at the top and in the final
# entry.  The resulting notebook is committed as the child of this HEAD.
text, count = re.subn(
    r"(notebook parent head: `)[0-9a-f]{7,40}(`)",
    rf"\g<1>{HEAD}\g<2>",
    text,
    count=1,
)
if count != 1:
    raise SystemExit("top notebook parent-head pin not updated")

text, count = re.subn(
    r"(This notebook\nrevision was authored against parent head `)[0-9a-f]{7,40}(`\.)",
    rf"\g<1>{HEAD}\g<2>",
    text,
    count=1,
)
if count != 1:
    raise SystemExit("final-entry parent-head pin not updated")
NOTEBOOK.write_text(text, encoding="utf-8")

# State the codimension-by-codimension bound via the effective Vogel/refined
# intersection cycles, rather than the insufficient phrase "minimal
# codimension c".
degree = DEGREE.read_text(encoding="utf-8")
old = """Let `I_A` be generated by a primitive homogeneous landing tuple of degree
`d` on `P4`.  If `Z` ranges over the irreducible components of the base scheme
having minimal codimension `c`, then `c` general degree-`d` members contain
those components with positive intersection multiplicity.  Refined Bézout
gives
\\[
\\sum_{\\operatorname{codim}Z=c}\\operatorname{mult}_Z\\deg Z\\le d^c.
\\tag{1.1}
\\]
"""
new = """Let `I_A` be generated by a primitive homogeneous landing tuple of degree
`d` on `P4`.  Choose general members successively and, at stage `r`, remove
the fixed components already produced in codimension `<r` (the
Vogel/refined-intersection construction).  The resulting codimension-`c`
cycle is effective, has degree at most `d^c`, and contains every
codimension-`c` base component isolated after the lower-codimension components
are removed, with positive local intersection multiplicity.  Hence
\\[
\\sum_{\\operatorname{codim}Z=c}\\operatorname{mult}_Z\\deg Z\\le d^c.
\\tag{1.1}
\\]
"""
if degree.count(old) != 1:
    raise SystemExit("degree-accounting introduction not found exactly once")
degree = degree.replace(old, new, 1)
old_tail = """For the last row, first saturate/remove the positive-dimensional components;
then four general members bound the residual zero-dimensional length by
`d^4`.  Equation (1.1) does not count a strict-support stratum that is merely
contained in a larger base component.
"""
new_tail = """For the curve and point rows, `component` means a component remaining after
lower-codimension base components are removed; the point row is the residual
zero-dimensional scheme.  These are the components controlled by the
effective Vogel cycles.  Equation (1.1) does not count a strict-support
stratum that is merely contained in a larger base component.
"""
if degree.count(old_tail) != 1:
    raise SystemExit("degree-accounting scope paragraph not found exactly once")
DEGREE.write_text(degree.replace(old_tail, new_tail, 1), encoding="utf-8")

# Register the real concurrent integration branch rather than exempting the
# remote-branch inventory check.
manifest = json.loads(MANIFEST.read_text(encoding="utf-8"))
known = manifest.setdefault("known_branches", [])
for branch in ("integrate/rt18-20260810", "integrate/v22-gates-20260810"):
    if branch not in known:
        known.append(branch)
known.sort()
MANIFEST.write_text(json.dumps(manifest, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")

for rel in (".github/workflows/rt_notebook_cleanup.yml", ".github/rt_notebook_cleanup.py"):
    path = ROOT / rel
    if path.exists():
        path.unlink()
